def zone_for(postcode):
    """The zone of a five digit postcode: first digit 0-2 is zone 1, 3-5 is zone 2, 6-8 is zone 3, 9 is zone 4 (remote)."""
    first = int(postcode[0])
    if first <= 2:
        return 1
    if first <= 5:
        return 2
    if first <= 8:
        return 3
    return 4

